    interface LegacyCallbacks {
        data?: (stream: IncomingMessage) => void;
        pdf?: (stream: IncomingMessage) => void;
        error?: (message: string, statusCode?: number | string, cause?: unknown) => void;
        end?: () => void;
    }

    // Modern conversions require content and error handlers; pdf aliases data.
    type Callbacks = LegacyCallbacks & {
        error: (message: string, statusCode?: number | string, cause?: unknown) => void;
    } & (
        {data: (stream: IncomingMessage) => void} |
        {pdf: (stream: IncomingMessage) => void}
    );

    type FileCallback = (error: Pdfcrowd.Error | null, filePath?: string) => void;

    function saveToFile(filePath: string, callback?: FileCallback): Callbacks;
    function sendHttpResponse(response: ServerResponse, disposition?: string, fileName?: string): Callbacks;
    function sendPdfInHttpResponse(response: ServerResponse, fileName?: string, disposition?: string): Callbacks;
    function sendImageInHttpResponse(response: ServerResponse, contentType: string, fileName: string, disposition?: string): Callbacks;
    function sendGenericHttpResponse(response: ServerResponse, contentType: string, fileName: string, disposition?: string): Callbacks;

    // The legacy client retains its callback-only interface.
    class Pdfcrowd {
        constructor(username: string, apikey: string, host?: string);
        convertHtml(html: string, callbacks?: LegacyCallbacks, options?: LegacyOptions): void;
        convertURI(uri: string, callbacks?: LegacyCallbacks, options?: LegacyOptions): void;
        convertFile(fileName: string, callbacks?: LegacyCallbacks, options?: LegacyOptions): void;
    }

    interface LegacyOptions {
        [name: string]: string | number | boolean;
    }

    namespace Pdfcrowd {
        // This SDK error is a subclass of the native Error constructor, so
        // `err instanceof Error` holds and it carries a real stack/cause.
        class Error extends globalThis.Error {
            constructor(error: string | globalThis.Error, httpCode?: number | string, cause?: unknown);
            // Declared explicitly: native Error only exposes `cause` when the
            // consumer targets ES2022+, but this SDK always sets it (see the
            // runtime fallback in pdfcrowd.js), so it must be visible at any target.
            cause: unknown;
            error: string;
            // Parsed codes are numeric; explicit string statuses are retained.
            httpCode: number | string | undefined;
            reasonCode: number;
            docLink: string;
            toString(): string;
            getStatusCode(): number | string | undefined;
            getReasonCode(): number;
            getMessage(): string;
            getDocumentationLink(): string;
        }
    }

